 const games=$('#games-page');const featured=document.createElement('div');featured.className='game-shelves';featured.innerHTML='<div class="game-shelf trending-games"><small>✦ TRENDING GAMES</small><b>Truth or tiny dare</b><span>Play in a lobby · 1.8k players</span><button data-game-shelf="Truth or tiny dare">Play with people ↗</button></div><div class="game-shelf newest-games"><small>✳ NEW THIS WEEK</small><b>Two truths & a fib</b><span>Guess which story is made up</span><button data-game-shelf="Two truths & a fib">Try the new game ↗</button></div>';games.insertBefore(featured,$('.game-feature',games));featured.querySelectorAll('[data-game-shelf]').forEach(x=>x.onclick=()=>{nav('chats');if(app.roomId)openGamePicker();else openHostLobby()});
