function updateProfile(){const u=app.user;if(!u)return;$('.profile-name').innerHTML=`${esc(u.name)} <span>✦</span>`;$('.profile-handle').textContent=`@${u.handle}`;$('.profile-bio').textContent=u.bio||'Making things, meeting people, collecting little moments ✨';$('.profile-avatar').innerHTML=`${u.avatarData?`<img src="${u.avatarData}" alt="Profile photo">`:esc((u.name||'T')[0].toUpperCase())}<button class="avatar-plus" aria-label="Change profile photo">＋</button>`;$('.profile-banner').style.backgroundImage=u.coverData?`linear-gradient(#1115,#1115),url("${u.coverData}")`:'';}
function mediaHtml(post){
 if(!post.mediaUrl)return '<div class="post-art art-dance seed-art text-art" data-style="'+esc(post.mediaFilter||'')+'"><div class="art-caption">'+esc(post.body||'A little moment')+'</div><span class="art-note">✳</span></div>';
 if(post.mediaType.startsWith('video/'))return '<video class="post-media" src="'+post.mediaUrl+'" playsinline controls preload="metadata" style="filter:'+filterCss(post.mediaFilter)+'"></video>';
 if(post.mediaType.startsWith('audio/'))return '<div class="audio-post-art"><b>♫</b><audio src="'+post.mediaUrl+'" controls></audio></div>';
 const urls=post.mediaUrls&&post.mediaUrls.length?post.mediaUrls:[post.mediaUrl];
 if(urls.length===1)return '<img class="post-media" src="'+urls[0]+'" alt="Post by '+esc(post.author.handle)+'" style="filter:'+filterCss(post.mediaFilter)+'">';
 return '<div class="media-carousel" data-carousel data-index="0" data-urls="'+esc(JSON.stringify(urls))+'"><img class="post-media" src="'+urls[0]+'" alt="Photo 1 of '+urls.length+' by '+esc(post.author.handle)+'" style="filter:'+filterCss(post.mediaFilter)+'"><button class="carousel-arrow prev" data-carousel-move="-1" aria-label="Previous photo">‹</button><button class="carousel-arrow next" data-carousel-move="1" aria-label="Next photo">›</button><span class="carousel-count">1 / '+urls.length+'</span><div class="carousel-dots">'+urls.map((_,i)=>'<button class="carousel-dot '+(i===0?'selected':'')+'" data-carousel-index="'+i+'" aria-label="Photo '+(i+1)+'"></button>').join('')+'</div></div>';
}
function moveCarousel(post,index){const carousel=$('[data-carousel]',post);if(!carousel)return;const urls=JSON.parse(carousel.dataset.urls||'[]');if(!urls.length)return;const next=(index+urls.length)%urls.length;carousel.dataset.index=next;const img=$('img',carousel);img.src=urls[next];img.alt='Photo '+(next+1)+' of '+urls.length;$('.carousel-count',carousel).textContent=(next+1)+' / '+urls.length;$$('.carousel-dot',carousel).forEach((b,i)=>b.classList.toggle('selected',i===next))}
function filterCss(name){return({mono:'grayscale(1)',warm:'sepia(.28) saturate(1.25)',bright:'brightness(1.12) saturate(1.2)',dream:'saturate(.78) contrast(.9)',none:'none'})[name]||'none'}
function card(post,index=0){const liked=post.liked?'liked':'',saved=post.saved?'saved':'';const avatar=post.author.avatarData?`<img class="avatar-photo" src="${post.author.avatarData}">`:esc((post.author.name||'T')[0].toUpperCase());return `<article class="post post-one" data-post-id="${post.id}" data-user="${esc(post.author.handle)}"><div class="post-art-wrap" data-gesture-area>${mediaHtml(post)}<div class="post-gradient"></div><button class="post-context-trigger" aria-label="Post options">•••</button><div class="post-copy"><div class="user-line"><button class="avatar profile-link">${avatar}</button><button class="profile-link user-handle">@${esc(post.author.handle)}</button><button class="follow-button ${post.author.following?'following':''}" data-follow="${post.author.id}">${post.author.following?'Following':'Follow'}</button></div><p>${esc(post.caption)}</p><span class="sound-line">♫ ${post.mediaType.startsWith('audio/')?'original audio':esc(post.author.name||'Trude creator')}</span></div><div class="post-actions"><button class="post-action like-action ${liked} ${saved}"><span>${post.liked?'♥':'♡'}</span><small>${human(post.likes)}</small></button><button class="post-action comment-action"><span>◌</span><small>${human(post.comments)}</small></button><button class="post-action share-action"><span>↗</span><small>Share</small></button><button class="record-disc" aria-label="Audio details">♫</button></div></div></article>`}
async function loadFeed(){try{const result=await api('/api/feed?tab='+encodeURIComponent(app.feed)),feed=$('#feed'),hidden=JSON.parse(localStorage.getItem('trude-not-interested-'+(app.user?.id||'guest'))||'[]'),visible=result.posts.filter(p=>!hidden.includes(Number(p.id)));feed.innerHTML=visible.length?visible.map(card).join(''):'<div class="empty-state"><span>✳</span><b>'+esc(app.feed==='Following'?'Follow a few people to start your Following feed.':'Your feed is waiting for its first post.')+'</b><button class="primary-btn" onclick="openAuth(\'signup\')">Join Trude</button></div>';feed.scrollTop=0;updateProfile()}catch(e){toast(e.message)}}
function authUserForPost(post){if(!requireLogin())throw Error('Sign in first');return app.user}
async function toggleLike(post){if(!requireLogin())return;try{const res=await send(`/api/posts/${post.dataset.postId}/like`),button=$('.like-action',post),number=$('small',button),n=Number(number.dataset.value||number.textContent.replaceAll(',',''));number.dataset.value=res.active?n+1:n-1;number.textContent=human(res.active?n+1:n-1);button.classList.toggle('liked',res.active);$('span',button).textContent=res.active?'♥':'♡'}catch(e){toast(e.message)}}
async function openComments(post){if(!requireLogin())return;let data;try{data=await api(`/api/posts/${post.dataset.postId}/comments`)}catch(e){toast(e.message);return}modal('Comments',`<div id="comment-list" class="comment-list">${data.comments.map(c=>`<div class="comment-row"><span class="chat-avatar peach">${esc(c.name[0])}</span><p><b>@${esc(c.handle)}</b><br>${esc(c.body)}</p></div>`).join('')||'<p class="empty-note">Be the first to say something kind.</p>'}</div><form id="comment-form"><input class="modal-field" name="body" maxlength="500" required placeholder="Add a comment..."><button class="modal-primary full-width">Post comment</button></form>`,true);$('#comment-form').onsubmit=async e=>{e.preventDefault();try{await send(`/api/posts/${post.dataset.postId}/comments`,{body:new FormData(e.currentTarget).get('body')});closeModal();await loadFeed();toast('Comment saved')}catch(error){toast(error.message)}}}
async function toggleSave(id){if(!requireLogin())return false;try{const r=await send(`/api/posts/${id}/save`);return r.active}catch(e){toast(e.message);return false}}
function openShare(post){if(!requireLogin())return;modal('Share this post',`<p>Copy a link to send anywhere, or share it with a Trude friend.</p><button class="secondary-btn full-width" id="copy-post-link">↗ &nbsp; Copy post link</button><button class="secondary-btn full-width" id="share-system">Share with your phone</button><label class="search-box"><span>⌕</span><input id="share-search" placeholder="Find a friend"></label><div id="share-people" class="people-list"></div><button class="secondary-btn full-width" id="repost-post">↻ &nbsp; Repost to your feed</button>`);$('#copy-post-link').onclick=async()=>{const link=`${location.origin}/#post/${post.dataset.postId}`;try{await navigator.clipboard.writeText(link);toast('Post link copied')}catch{prompt('Copy this Trude post link',link)};try{await send(`/api/posts/${post.dataset.postId}/share`,{})}catch{}};$('#share-system').onclick=async()=>{const url=`${location.origin}/#post/${post.dataset.postId}`;if(navigator.share)await navigator.share({title:'Trude post',url});else navigator.clipboard?.writeText(url).then(()=>toast('Link copied'))};$('#share-search').oninput=async e=>{if(e.target.value.length<2){$('#share-people').innerHTML='';return}try{const r=await api(`/api/search?q=${encodeURIComponent(e.target.value)}`);$('#share-people').innerHTML=r.users.filter(u=>u.id!==app.user.id).map(u=>`<button class="person-row" data-recipient="${u.id}"><span class="chat-avatar blue">${esc(u.name[0])}</span>@${esc(u.handle)} <span>Send ↗</span></button>`).join('')||'<p class="empty-note">No creators found.</p>';$$('[data-recipient]').forEach(b=>b.onclick=async()=>{try{await send(`/api/posts/${post.dataset.postId}/share`,{recipientId:Number(b.dataset.recipient)});toast('Sent to your Trude friend');closeModal()}catch(err){toast(err.message)}})}catch(err){toast(err.message)}};$('#repost-post').onclick=async()=>{try{await send(`/api/posts/${post.dataset.postId}/share`,{});toast('Repost saved to Shared');closeModal()}catch(e){toast(e.message)}}}
function openPostMenu(post){const id=post.dataset.postId;modal('Post options',`<div class="post-menu-grid"><button data-menu="save">▤ &nbsp; ${$('.like-action',post).classList.contains('saved')?'Remove from saved':'Add to saved'}</button><button data-menu="speed">▶ &nbsp; Playback speed</button><button data-menu="clear">□ &nbsp; Clear display</button><button data-menu="auto">⇵ &nbsp; Auto scroll</button><button data-menu="download">↓ &nbsp; Download media</button><button data-menu="story">＋ &nbsp; Add to story</button><button data-menu="not">⊘ &nbsp; Not interested</button><button data-menu="data">◉ &nbsp; Data saver</button><button data-menu="report">⚑ &nbsp; Report</button><button data-menu="share">↗ &nbsp; Share</button><button data-menu="search">⌕ &nbsp; Search this creator</button></div><p class="menu-social">Share with space &nbsp; · &nbsp; Repost</p>`);$$('[data-menu]').forEach(b=>b.onclick=async()=>{closeModal();switch(b.dataset.menu){case'save':{const active=await toggleSave(id);if(active)toast('Added to Saved');await loadFeed();break}case'speed':menuChoice('Playback speed','1×','0.5×','1.5×','2×',value=>{const v=$('video',post);if(v)v.playbackRate=Number(value.replace('×',''));toast(`Playback set to ${value}`)});break;case'clear':post.classList.toggle('clear-display');toast('Tap once to restore the post details');break;case'auto':toggleAutoScroll();break;case'download':downloadPost(post);break;case'story':toast('Stories need expiry and audience controls before they are enabled');break;case'data':{const on=!document.documentElement.classList.contains('data-saver');document.documentElement.classList.toggle('data-saver',on);localStorage.setItem('trude-data-saver',on?'1':'0');document.querySelectorAll('video').forEach(v=>{if(on){v.pause();v.preload='none'}});toast(on?'Data saver on':'Data saver off');break}case'not':{const key='trude-not-interested-'+(app.user?.id||'guest'),hidden=JSON.parse(localStorage.getItem(key)||'[]');hidden.push(Number(id));localStorage.setItem(key,JSON.stringify([...new Set(hidden)]));post.remove();toast('We’ll show fewer posts like this');break}case'report':modal('Report post',`<p>Tell us what feels wrong. Your report is saved for the Trude team.</p><select class="modal-field" id="report-reason"><option>Bullying or harassment</option><option>Unsafe content</option><option>Spam</option><option>Something else</option></select><button class="modal-primary full-width" id="submit-report">Send report</button>`);$('#submit-report').onclick=async()=>{try{await send(`/api/posts/${id}/report`,{reason:$('#report-reason').value});closeModal();toast('Report sent')}catch(e){toast(e.message)}};break;case'share':openShare(post);break;case'search':$('#search-input').value=post.dataset.user.slice(1);nav('explore');await searchExplore(post.dataset.user);break}})}
function menuChoice(title,...args){const choices=args.slice(0,-1),onChoose=args.at(-1);modal(title,`<div class="choice-list">${choices.map(c=>`<button data-choice="${esc(c)}">${esc(c)}</button>`).join('')}</div>`);$$('[data-choice]').forEach(b=>b.onclick=()=>{closeModal();onChoose(b.dataset.choice)})}
let autoTimer;function toggleAutoScroll(){const root=document.documentElement;root.classList.toggle('auto-scroll');clearInterval(autoTimer);if(root.classList.contains('auto-scroll'))autoTimer=setInterval(()=>{const feed=$('#feed');feed.scrollBy({top:feed.clientHeight,behavior:'smooth'})},5000);toast(root.classList.contains('auto-scroll')?'Auto scroll on':'Auto scroll off')}
function downloadPost(post){const media=$('.post-media',post);if(!media){toast('This text post has no media to download');return}const a=document.createElement('a');a.href=media.src;a.download=`trude-post-${post.dataset.postId}`;a.click();toast('Download started')}
function wireFeedTabs(){$$('.feed-tab').forEach(b=>b.onclick=async()=>{$$('.feed-tab').forEach(t=>t.classList.toggle('selected',t===b));app.feed=b.dataset.feed;$('.feed-tabs').classList.toggle('following',app.feed==='Following');await loadFeed()})}
function wireGestures(){
 $('#feed').addEventListener('click',async e=>{const post=e.target.closest('.post');if(!post)return;if(e.target.closest('[data-carousel-move]'))return moveCarousel(post,Number($('.media-carousel',post).dataset.index)+Number(e.target.closest('[data-carousel-move]').dataset.carouselMove));if(e.target.closest('[data-carousel-index]'))return moveCarousel(post,Number(e.target.closest('[data-carousel-index]').dataset.carouselIndex));if(e.target.closest('.like-action'))return toggleLike(post);if(e.target.closest('.comment-action'))return openComments(post);if(e.target.closest('.share-action'))return openShare(post);if(e.target.closest('.post-context-trigger'))return openPostMenu(post);if(e.target.closest('.follow-button'))return toggleFollow(Number(e.target.closest('.follow-button').dataset.follow),e.target.closest('.follow-button'));if(e.target.closest('.profile-link'))return showProfile(post.dataset.user.slice(1));if(e.target.closest('.record-disc'))return toast('Original sound by this creator')});
 $('#feed').scrollTop=0;$('#feed').addEventListener('pointerdown',e=>{const area=e.target.closest('[data-gesture-area]');if(!area||e.target.closest('button,a,input,video,audio'))return;const post=area.closest('.post');const start={x:e.clientX,y:e.clientY,t:Date.now(),path:[[e.clientX,e.clientY]]};area.dataset.longHeld='';app.hold=setTimeout(()=>{area.dataset.longHeld='1';openPostMenu(post)},550);area.setPointerCapture?.(e.pointerId);area.dataset.down=JSON.stringify(start)});
 $('#feed').addEventListener('pointermove',e=>{const area=e.target.closest('[data-gesture-area]');if(!area?.dataset.down)return;const d=JSON.parse(area.dataset.down);d.path.push([e.clientX,e.clientY]);area.dataset.down=JSON.stringify(d);if(Math.hypot(e.clientX-d.x,e.clientY-d.y)>22)clearTimeout(app.hold)});
 $('#feed').addEventListener('pointerup',e=>{const area=e.target.closest('[data-gesture-area]');if(!area?.dataset.down)return;clearTimeout(app.hold);const d=JSON.parse(area.dataset.down),wasHeld=area.dataset.longHeld==='1';delete area.dataset.down;delete area.dataset.longHeld;if(wasHeld)return;if(Math.hypot(e.clientX-d.x,e.clientY-d.y)<16){const id=area.closest('.post').dataset.postId,t=Date.now();if(t-(app.lastTapAt?.[id]||0)<320){toggleLike(area.closest('.post'));app.lastTapAt={}}else app.lastTapAt={...(app.lastTapAt||{}),[id]:t};return}if(isC(d.path)){openComments(area.closest('.post'))}});
 $('#feed').addEventListener('pointercancel',()=>clearTimeout(app.hold));
}
function isC(points){if(points.length<6)return false;const [sx,sy]=points[0],[ex,ey]=points.at(-1),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),w=Math.max(...xs)-Math.min(...xs),h=Math.max(...ys)-Math.min(...ys);if(w<38||h<55||Math.abs(ey-sy)>h*.55)return false;const first=points[Math.floor(points.length*.2)],middle=points[Math.floor(points.length*.55)],last=points[Math.floor(points.length*.85)];return first[0]<sx-w*.4&&middle[1]>sy&&last[0]>middle[0]+w*.22}
