async function showProfile(handle){if(!handle){if(!requireLogin())return;handle=app.user.handle}try{const {profile,locked,counts,posts,following}=await api(`/api/profiles/${encodeURIComponent(handle)}`);app.profile={profile,locked,counts,posts,following};nav('profile');renderProfile()}catch(e){toast(e.message)}}
function renderProfile(){if(!app.profile)return;const {profile:p,locked,counts:c,posts,following}=app.profile,own=app.user?.id===p.id;$('.profile-banner').innerHTML=`<span>${own?'YOUR LITTLE CORNER':`@${esc(p.handle)}`}</span><button class="icon-btn profile-settings" aria-label="Settings">⚙</button>`;$('.profile-banner').style.backgroundImage=p.coverData?`linear-gradient(#1115,#1115),url("${p.coverData}")`:'';$('.profile-top').innerHTML=`<button class="profile-avatar profile-image-open">${p.avatarData?`<img src="${p.avatarData}" alt="${esc(p.name)}">`:esc(p.name[0].toUpperCase())}${own?'<span class="avatar-plus">＋</span>':''}</button>${own?'<button class="edit-profile">Edit profile</button>':`<button class="edit-profile profile-follow ${following?'is-following':''}" data-follow="${p.id}">${following?'Following':'Follow'}</button>`}`;$('.profile-name').innerHTML=`${esc(p.name)} ${own?'<span>✦</span>':''}`;$('.profile-handle').textContent=`@${p.handle}`;$('.profile-bio').textContent=p.bio||'No bio yet';$('.profile-stats').innerHTML=`<button data-profile-list="following"><b>${human(c.following)}</b><small>Following</small></button><button data-profile-list="followers"><b>${human(c.followers)}</b><small>Followers</small></button><button data-profile-analytics><b>${human(c.likes)}</b><small>Likes</small></button>`;const website=$('.profile-bio');let link=$('#profile-website');if(!link){link=document.createElement('a');link.id='profile-website';link.target='_blank';link.rel='noopener';website.after(link)}link.href=/^https?:\/\//i.test(p.website)?p.website:`https://${p.website}`;link.textContent=p.website||'';link.classList.toggle('hidden',!p.website);
 const tabs=$$('.profile-tabs button');tabs.forEach(b=>b.classList.toggle('hidden',!own&&['Liked','Saved','Shared','Locked'].includes(b.dataset.profileTab)));$('.profile-tabs').classList.toggle('hidden',locked);$('.profile-posts').innerHTML=locked?`<div class="private-message">🔒 <b>This account is private</b><span>Follow to see their posts.</span></div>`:posts.map(p=>`<button class="profile-tile" data-open-profile-post="${p.id}">${p.mediaUrl?`<img src="${p.mediaUrl}">`:`<span>✳</span><small>${esc(p.caption||p.body)}</small>`}</button>`).join('')||'<div class="empty-note">No posts here yet.</div>';
 $$('.profile-stats [data-profile-list]').forEach(b=>b.onclick=()=>showPeopleList(p.id,b.dataset.profileList));$('[data-profile-analytics]')?.addEventListener('click',()=>showAnalytics(p.id));$('.profile-follow')?.addEventListener('click',async e=>{try{const r=await send(`/api/profiles/${p.id}/follow`);app.profile.following=r.following;renderProfile()}catch(err){toast(err.message)}});$('.edit-profile')?.addEventListener('click',()=>editProfile(p));$('.profile-image-open')?.addEventListener('click',e=>{if(e.target.closest('.avatar-plus')){e.stopPropagation();editImage('avatar',p.avatarData)}else showFullImage(p.avatarData||p.coverData)});$('.profile-banner .profile-settings').onclick=()=>openSettings(p);$$('[data-profile-tab]').forEach(b=>b.onclick=async()=>{if(b.dataset.profileTab==='Posts'){app.profile.posts=(await api('/api/feed?tab=Posts')).posts}else{const r=await api(`/api/feed?tab=${b.dataset.profileTab}`);app.profile.posts=r.posts}$$('[data-profile-tab]').forEach(t=>t.classList.toggle('chosen',t===b));$('.profile-posts').innerHTML=app.profile.posts.map(p=>`<button class="profile-tile">${p.mediaUrl?`<img src="${p.mediaUrl}">`:'✳'}</button>`).join('')});$$('[data-open-profile-post]').forEach(b=>b.onclick=()=>{nav('home');loadFeed().then(()=>document.querySelector(`[data-post-id="${b.dataset.openProfilePost}"]`)?.scrollIntoView({behavior:'smooth'}))});}
async function showPeopleList(id,type){try{const r=await api(`/api/profiles/${id}/${type}`);modal(type==='followers'?'Followers':'Following',`<div class="people-list">${r.users.map(u=>`<button class="person-row profile-result" data-handle="${esc(u.handle)}"><span class="chat-avatar blue">${esc(u.name[0])}</span><span><b>${esc(u.name)}</b><small>@${esc(u.handle)}</small></span><span>›</span></button>`).join('')||'<p class="empty-note">No one here yet.</p>'}</div>`);$$('.profile-result').forEach(b=>b.onclick=()=>{closeModal();showProfile(b.dataset.handle)})}catch(e){toast(e.message)}}
