function editImage(which,current){modal(which==='avatar'?'Change profile photo':'Change cover photo',`<p>Choose an image from your device. Trude keeps it with your profile.</p><label class="upload-box"><span>▧</span><b>Choose a photo or take one</b><small>JPG, PNG, or WebP</small><input id="profile-image-file" type="file" accept="image/*" capture="environment" hidden></label><button class="modal-primary full-width" id="save-profile-image">Save photo</button>`);const file=$('#profile-image-file');$('.upload-box').onclick=()=>file.click();let data=current||'';file.onchange=()=>{const f=file.files[0];if(!f)return;if(f.size>2*1024*1024)return toast('Choose a photo under 2 MB');const reader=new FileReader();reader.onload=()=>{data=reader.result;$('.upload-box b').textContent=f.name};reader.readAsDataURL(f)};$('#save-profile-image').onclick=async()=>{if(!data)return toast('Choose a photo first');try{const r=await send(`/api/profiles/${app.user.id}/${which}`,{data});app.user=r.user;app.profile.profile=r.user;updateProfile();renderProfile();closeModal()}catch(e){toast(e.message)}}}
