function editProfile(p){modal('Edit profile',`<form id="profile-edit-form" class="auth-form"><label>Name<input name="name" value="${esc(p.name)}" required maxlength="40"></label><small class="auth-footnote">Display name can be changed every 3 months.</small><label>Handle<input name="handle" value="${esc(p.handle)}" required maxlength="24"></label><label>Bio<textarea name="bio" maxlength="240" rows="3">${esc(p.bio)}</textarea></label><label>Link<input name="website" value="${esc(p.website)}" placeholder="https://your-site.example"></label><div id="edit-error" class="form-error"></div><button class="modal-primary">Save changes</button></form>`,true);$('#profile-edit-form').onsubmit=async e=>{e.preventDefault();try{const r=await send(`/api/profiles/${app.user.id}/update`,Object.fromEntries(new FormData(e.currentTarget).entries()));app.user=r.user;app.profile.profile=r.user;updateProfile();renderProfile();closeModal();toast('Profile saved')}catch(error){$('#edit-error').textContent=error.message}}}
function openSettings(p){modal('Settings',`<div class="settings-list"><button data-setting="privacy">🔒 &nbsp; Privacy <span>${p.private?'Private':'Public'} ›</span></button><button data-setting="analytics">▥ &nbsp; Analytics <span>Likes, follows, activity ›</span></button><button data-setting="cover">▧ &nbsp; Edit cover photo <span>›</span></button><button data-setting="security">♧ &nbsp; Sign-in & security <span>›</span></button><button data-setting="logout">↗ &nbsp; Sign out <span>›</span></button></div><p class="auth-footnote">Trude points live in Analytics. They are test points and have no cash value.</p>`);$$('[data-setting]').forEach(b=>b.onclick=async()=>{switch(b.dataset.setting){case'privacy':try{const r=await send(`/api/profiles/${p.id}/update`,{name:p.name,handle:p.handle,bio:p.bio,website:p.website,private:!p.private});app.user=r.user;app.profile.profile=r.user;renderProfile();openSettings(r.user);toast(r.user.private?'Private account on':'Account is public')}catch(e){toast(e.message)}break;case'analytics':closeModal();showAnalytics(p.id);break;case'cover':closeModal();editCover();break;case'security':closeModal();openAuth('forgot');break;case'logout':await send('/api/auth/logout');app.user=null;app.profile=null;closeModal();updateProfile();await loadFeed();openAuth('login');break}})}
function roomCard(room){return '<article class="public-room"><span class="live-pill"><i></i> '+(room.hostId===app.user?.id?'YOUR ROOM':'OPEN')+'</span><h3>'+esc(room.title)+'</h3><p>Hosted by @'+esc(room.hostHandle)+' · '+room.members+'/'+room.capacity+' people · '+room.durationMinutes+' min</p><button class="secondary-btn" data-join-room="'+room.id+'">'+(room.joined?'Open chat':'Join conversation')+' ↗</button></article>'}
function loadRooms(){const target=$('#chat-room-list');if(!app.user){target.innerHTML='<div class="explore-empty"><span>◌</span><b>Sign in to find a lobby</b><button class="primary-btn" id="signin-room">Create account</button></div>';$('#signin-room').onclick=()=>openAuth('signup');return}api('/api/rooms').then(r=>{target.innerHTML='<button class="lobby-create-card" id="host-lobby"><span>＋</span><b>Host a lobby</b><small>Choose a room size, topic, and time</small></button>'+(r.rooms.map(roomCard).join('')||'<p class="empty-note">No open rooms right now. Start one and invite people in.</p>');$('#host-lobby').onclick=openHostLobby;$$('[data-join-room]',target).forEach(b=>b.onclick=()=>joinRoom(Number(b.dataset.joinRoom)))}).catch(e=>toast(e.message))}
async function loadLobbyDirectory(){if(!app.user){$('#popular-hosts').innerHTML='<p class="empty-note">Sign in to browse and join hosted rooms.</p>';$('#public-rooms').innerHTML='';return}try{const r=await api('/api/rooms');$('#public-rooms').innerHTML=r.rooms.map(roomCard).join('')||'<p class="empty-note">No rooms open yet. Be the first host.</p>';$$('[data-join-room]',$('#public-rooms')).forEach(b=>b.onclick=()=>joinRoom(Number(b.dataset.joinRoom)));const hosts=[...new Map(r.rooms.map(x=>[x.hostId,x])).values()];$('#popular-hosts').innerHTML=hosts.map(room=>'<button class="person-row" data-join-room="'+room.id+'"><span class="chat-avatar peach">'+esc(room.hostName[0])+'</span><span><b>'+esc(room.hostName)+'</b><small>@'+esc(room.hostHandle)+' · '+room.members+' in their room</small></span><span>↗</span></button>').join('')||'<p class="empty-note">Popular hosts will appear when people open rooms.</p>';$$('[data-join-room]',$('#popular-hosts')).forEach(b=>b.onclick=()=>joinRoom(Number(b.dataset.joinRoom)))}catch(e){toast(e.message)}}
function openHostLobby(){if(!requireLogin())return;modal('Host a lobby',`<form id="host-form" class="auth-form"><label>What’s the room about?<input name="title" maxlength="70" placeholder="Music, games, weekend plans…" required></label><label>People in the room<select name="capacity"><option value="4">4 people</option><option value="8">8 people</option><option value="20" selected>20 people</option></select></label><label>Room duration<select name="duration"><option value="15">15 minutes</option><option value="30" selected>30 minutes</option><option value="60">60 minutes</option><option value="120">2 hours</option></select></label><button class="modal-primary">Create lobby</button></form><p class="auth-footnote">Each room has an invite link. Hosts can share it with up to 20 friends.</p>`);$('#host-form').onsubmit=async e=>{e.preventDefault();try{const r=await send('/api/rooms',Object.fromEntries(new FormData(e.currentTarget).entries()));closeModal();await joinRoom(r.room)}catch(err){toast(err.message)}}}
async function joinRoom(id){if(!requireLogin())return;try{const r=await send(`/api/rooms/${id}/join`);app.roomId=id;app.roomSince=0;renderRoom(r.room);nav('chats');startRoomPolling()}catch(e){toast(e.message)}}
function renderRoom(room){let panel=$('#active-room');if(!panel){panel=document.createElement('section');panel.id='active-room';panel.className='room-detail hidden';$('#chats-page').append(panel)}panel.innerHTML=`<div class="room-top"><button id="leave-lobby">← Rooms</button><span class="live-pill"><i></i> ${room.status==='open'?'LIVE':'ENDED'}</span><b>${Math.max(0,Math.ceil((Date.parse(room.expiresAt)-Date.now())/60000))} min left</b></div><h2>${esc(room.title)}</h2><p class="room-sub">Hosted by @${esc(room.hostHandle)} · ${room.members}/${room.capacity} people</p><div class="room-invite"><button class="secondary-btn" id="invite-friends">＋ Invite friends</button><button class="secondary-btn" id="room-play">✳ Start a game</button></div><div id="chat-messages" class="chat-messages"></div><form id="chat-form" class="chat-compose"><input id="chat-input" placeholder="Say something kind…"><button aria-label="Send">↑</button></form><small class="room-safety">✳ Keep it kind. Report anything that doesn’t feel right.</small>`;panel.classList.remove('hidden');$('#chat-room-list').classList.add('hidden');$('#leave-lobby').onclick=async()=>{try{await send(`/api/rooms/${app.roomId}/leave`)}catch{}clearInterval(app.poll);app.roomId=null;panel.classList.add('hidden');$('#chat-room-list').classList.remove('hidden');loadRooms()};$('#chat-form').onsubmit=async e=>{e.preventDefault();try{await send(`/api/rooms/${app.roomId}/messages`,{body:$('#chat-input').value});$('#chat-input').value='';await pollRoom()}catch(err){toast(err.message)}};$('#invite-friends').onclick=async()=>{const link=`${location.origin}/#room/${app.roomId}`;try{await navigator.clipboard.writeText(link);toast('Room invite link copied')}catch{prompt('Copy lobby invite link',link)}};$('#room-play').onclick=()=>openGamePicker();}
async function pollRoom(){if(!app.roomId)return;try{const r=await api(`/api/rooms/${app.roomId}/messages?after=${app.roomSince}`);const list=$('#chat-messages');for(const m of r.messages){const row=document.createElement('div');row.innerHTML=`<span class="chat-avatar blue">${esc(m.name[0])}</span><p><b>@${esc(m.handle)}</b><br>${esc(m.body)}</p>`;list.append(row);app.roomSince=Math.max(app.roomSince,m.id)}list.scrollTop=list.scrollHeight}catch(e){}}
