async function openGamePicker(){if(!requireLogin())return;modal('Play together',`<p>Choose a game for this lobby. Everyone in the room can play and chat together.</p><div class="game-list">${['Truth or tiny dare','This or that','Guess the sound','Word scramble'].map((g,i)=>`<button class="game-item" data-play-game="${g}"><span class="game-icon peach-bg">${['✳','↔','♫','Aa'][i]}</span><span><b>${g}</b><small>Play in this room</small></span><span>↗</span></button>`).join('')}</div>`);$$('[data-play-game]').forEach(b=>b.onclick=()=>openGame(b.dataset.playGame))}
const prompts={'Truth or tiny dare':['Truth: What’s a tiny thing that always makes your day better?','Dare: Do your best runway walk for 5 seconds.'],'This or that':['Treehouse or secret clubhouse?'],'Guess the sound':['Rain on a tent — name that sound!'],'Word scramble':['Unscramble: R U D T E']};
function openGame(game){if(!app.roomId){toast('Join a lobby or host a room to play together');return}let prompt=prompts[game]||prompts['Truth or tiny dare'];modal(game,`<div class="game-prompt"><small>YOUR ROOM · YOUR TURN</small><b id="prompt-text">${esc(prompt[0])}</b></div><div class="choice-row"><button id="game-truth">Truth</button><button id="game-dare">Tiny dare</button><button id="game-next">Another one</button></div><textarea class="modal-field" id="game-answer" rows="2" placeholder="Share your answer with the room…"></textarea><button class="modal-primary full-width" id="game-send">Send to room</button>`);$('#game-truth').onclick=()=>$('#prompt-text').textContent=prompt[0];$('#game-dare').onclick=()=>$('#prompt-text').textContent=prompt[1]||prompt[0];$('#game-next').onclick=()=>$('#prompt-text').textContent=prompt[Math.floor(Math.random()*prompt.length)];$('#game-send').onclick=async()=>{const text=$('#game-answer').value.trim();if(!text)return toast('Add your answer first');try{await send(`/api/rooms/${app.roomId}/messages`,{body:`🎮 ${text}`});await pollRoom();closeModal()}catch(e){toast(e.message)}}}
function activateLobbyGestures(){const b=$('[data-page="lobby"]');let timer;b.addEventListener('pointerdown',()=>{app.chatPress=false;timer=setTimeout(()=>{app.chatPress=true;nav('chats')},3000)});['pointerup','pointerleave','pointercancel'].forEach(e=>b.addEventListener(e,()=>clearTimeout(timer)));b.addEventListener('click',e=>{if(app.chatPress){e.preventDefault();e.stopPropagation();app.chatPress=false}},{capture:true});$('#host-lobby-top').onclick=openHostLobby}
