function openLiveSetup(){modal('Set up your LIVE',`<form id="live-form" class="auth-form"><label>What is this LIVE for?<select name="kind"><option>Chat and hangout</option><option>Gaming</option><option>Performance</option><option>Show and tell</option></select></label><label>LIVE title<input name="title" maxlength="80" placeholder="What should people expect?"></label><label>Co-host layout<select name="layout"><option value="4">Up to 4 people · gaming / co-host</option><option value="20">Up to 20 people · panel room</option></select></label><label class="switch-row"><input type="checkbox" name="background"> Preview background blur</label><label>Filter<select name="filter"><option>Natural</option><option>Warm</option><option>Soft light</option><option>Mono</option></select></label><div class="editor-preview" id="live-preview"><span>Camera preview is off</span><video id="live-video" autoplay playsinline muted></video></div><div class="editor-tools"><button type="button" class="secondary-btn" id="camera-preview">Turn camera preview on</button><button type="button" class="secondary-btn" id="screen-share">Share screen</button></div><div class="auth-footnote">This device-only preview does not broadcast to viewers yet. Multi-device LIVE needs a streaming service and signaling server.</div><button class="modal-primary full-width" id="start-live-room">Create LIVE room</button></form>`,true);let stream;$('#camera-preview').onclick=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});$('#live-video').srcObject=stream;$('#live-preview span').remove();toast('Camera preview on — not broadcasting')}catch{toast('Camera permission was not granted')}};$('#screen-share').onclick=async()=>{try{stream=await navigator.mediaDevices.getDisplayMedia({video:true});$('#live-video').srcObject=stream;$('#live-preview span').remove();toast('Screen preview on — not broadcasting')}catch{toast('Screen share was cancelled')}};$('#live-form').onsubmit=async e=>{e.preventDefault();stream?.getTracks().forEach(t=>t.stop());try{const b=Object.fromEntries(new FormData(e.currentTarget).entries());const r=await send('/api/rooms',{title:`LIVE · ${b.title||b.kind}`,capacity:Number(b.layout),duration:60});closeModal();await joinRoom(r.room)}catch(err){toast(err.message)}}}
function mediaEditor(type){const image=type==='Image',accept=image?'image/*':'video/*';modal(image?'Create a photo post':'Edit your video',`<div class="editor-import"><label class="upload-box"><span>${image?'▧':'▶'}</span><b>Import, take a photo, or record</b><small>Capture uses your device camera</small><input id="creator-file" type="file" accept="${accept}" capture="environment" ${image?'multiple':''} hidden></label><button class="secondary-btn" id="ai-image">✦ Generate with AI</button><p class="auth-footnote" id="editor-note">${image?'AI image generation needs a connected provider.':'Trim, add a caption overlay, and choose a look before posting.'}</p></div><div class="editor-preview" id="media-preview"><span>Choose media to preview it here</span></div>${image?'<div class="editor-tools">':'<label class="range-label">Trim start <input id="trim-start" type="range" min="0" max="90" value="0"></label><label class="range-label">Trim end <input id="trim-end" type="range" min="10" max="100" value="100"></label><div class="editor-tools">'}${['none','warm','bright','mono','dream'].map(f=>`<button type="button" class="filter-chip" data-filter="${f}">${f}</button>`).join('')}</div><label class="auth-form">Caption overlay<input id="caption-overlay" placeholder="Add text to your ${image?'photo':'video'}"></label><textarea class="modal-field" id="post-caption" maxlength="500" placeholder="Write a caption…"></textarea><div class="editor-tools"><button type="button" class="secondary-btn" id="add-audio">♫ Add sound</button><select id="post-visibility" class="modal-field"><option value="public">Public post</option><option value="followers">Followers only</option><option value="private">Only me · locked</option></select></div><button class="modal-primary full-width" id="publish-media">Share post</button>`,true);const file=$('#creator-file');$('.upload-box').onclick=()=>file.click();let mediaData='',mediaItems=[],mediaType='',activeFilter='none';file.onchange=async()=>{const files=[...file.files];if(!files.length)return;if(image&&files.length>6)return toast('Choose up to 6 photos');const total=files.reduce((n,f)=>n+f.size,0);if(total>7*1024*1024)return toast('Keep the combined upload under 7 MB');if(!image&&files[0].size>7*1024*1024)return toast('Choose a video under 7 MB');mediaType=files[0].type;try{mediaItems=await Promise.all(files.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f)})));mediaData=mediaItems[0];$('#media-preview').innerHTML=image?'<img id="preview-media" src="'+mediaData+'"><div class="preview-overlay" id="preview-overlay"></div>'+(mediaItems.length>1?'<span class="carousel-count">1 / '+mediaItems.length+' photos</span>':''):'<video id="preview-media" src="'+mediaData+'" controls playsinline></video><div class="preview-overlay" id="preview-overlay"></div>';$('.upload-box b').textContent=files.length>1?files.length+' photos selected':files[0].name}catch{toast('Could not read that media file')}};$('#caption-overlay').oninput=e=>{const overlay=$('#preview-overlay');if(overlay)overlay.textContent=e.target.value};$$('[data-filter]').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));$('#preview-media')?.style.setProperty('filter',filterCss(activeFilter))});$('#ai-image').onclick=()=>toast('AI image provider is not connected yet');$('#add-audio').onclick=()=>toast('Pick a licensed sound library after audio rights are configured');$('#publish-media').onclick=async()=>{if(!mediaData)return toast('Choose or capture a file first');try{await send('/api/posts',{mediaData,mediaItems:mediaItems.length>1?mediaItems:undefined,mediaType,caption:$('#post-caption').value,body:$('#caption-overlay').value,filter:activeFilter,visibility:$('#post-visibility').value});closeModal();nav('home');app.feed='For you';await loadFeed();toast('Post shared and saved to your account')}catch(e){toast(e.message)}}}
function textEditor(){modal('Make a text post',`<textarea class="modal-field" id="text-body" rows="5" maxlength="3000" placeholder="What’s on your mind?"></textarea><div class="text-style-options"><button data-font="bold">Bold</button><button data-font="serif">Serif</button><button data-font="mono">Mono</button><button data-font="glow">Glow</button></div><div class="editor-preview text-preview" id="text-preview">Your words go here</div><input class="modal-field" id="text-caption" placeholder="Add a caption"><button class="modal-primary full-width" id="publish-text">Share text post</button>`,true);$('#text-body').oninput=e=>$('#text-preview').textContent=e.target.value||'Your words go here';$$('[data-font]').forEach(b=>b.onclick=()=>{$$('.text-style-options button').forEach(x=>x.classList.toggle('selected',x===b));$('#text-preview').dataset.style=b.dataset.font});$('#publish-text').onclick=async()=>{const body=$('#text-body').value.trim();if(!body)return toast('Write a little something first');try{await send('/api/posts',{body,caption:$('#text-caption').value,mediaType:'text/plain'});closeModal();nav('home');await loadFeed();toast('Text post shared')}catch(e){toast(e.message)}}}
function audioEditor(){modal('Make an audio post',`<p>Record a voice note or import an audio file. The preview controls stay on this device.</p><div class="editor-tools"><button class="secondary-btn" id="record-audio">● Record</button><button class="secondary-btn" id="stop-audio" disabled>■ Stop</button><label class="secondary-btn file-button">Import audio<input type="file" id="audio-file" accept="audio/*" hidden></label></div><div id="audio-preview" class="editor-preview"><span>Audio waveform preview</span></div><label>Voice effect<select id="voice-effect" class="modal-field"><option>Original</option><option>Echo</option><option>Low pitch</option><option>High pitch</option></select></label><textarea class="modal-field" id="audio-caption" placeholder="Add a caption"></textarea><button class="modal-primary full-width" id="publish-audio">Share audio</button><p class="auth-footnote">Voice filters are preview-only; audio processing is not connected yet.</p>`,true);let recorder,chunks=[];$('#record-audio').onclick=async()=>{try{const s=await navigator.mediaDevices.getUserMedia({audio:true});recorder=new MediaRecorder(s);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{$('#audio-preview').innerHTML='<audio controls src="'+URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}))+'"></audio>';s.getTracks().forEach(t=>t.stop())};chunks=[];recorder.start();$('#record-audio').disabled=true;$('#stop-audio').disabled=false}catch{toast('Microphone permission was not granted')}};$('#stop-audio').onclick=()=>{recorder?.stop();$('#record-audio').disabled=false;$('#stop-audio').disabled=true};let audioData='';$('#audio-file').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>8*1024*1024)return toast('Choose an audio file under 8 MB');const reader=new FileReader();reader.onload=()=>{audioData=reader.result;$('#audio-preview').innerHTML=`<audio controls src="${audioData}"></audio>`};reader.readAsDataURL(f)};$('#publish-audio').onclick=async()=>{if(!audioData)return toast('Record or import an audio file');try{await send('/api/posts',{mediaData:audioData,mediaType:'audio/webm',caption:$('#audio-caption').value});closeModal();nav('home');await loadFeed();toast('Audio post shared')}catch(e){toast(e.message)}}}
function openProfileTabActions(){const p=$('.profile-banner');p.onclick=e=>{if(e.target.closest('.profile-settings'))return;if(!app.user)return;editCover()}}
async function bootstrap(){ensureExtraPages();wireFeedTabs();wireGestures();activateLobbyGestures();$$('.nav-item').forEach(b=>b.onclick=()=>{const page=b.dataset.page==='search'?'explore':b.dataset.page;if(page==='profile')showProfile(app.user?.handle);else nav(page)});$('.notification-btn').onclick=()=>modal('Notifications',`<p>Notifications from your Trude friends will show up here.</p>`);$('#create-button').onclick=openCreateWheel;$('#create-button').addEventListener('pointerdown',()=>{app.createHold=setTimeout(openCreateWheel,350)});['pointerup','pointerleave','pointercancel'].forEach(e=>$('#create-button').addEventListener(e,()=>clearTimeout(app.createHold)));$('#close-wheel').onclick=()=>$('#create-wheel').classList.add('hidden');$('.wheel-backdrop').onclick=()=>$('#create-wheel').classList.add('hidden');$$('[data-create]').forEach(b=>b.onclick=()=>{$('#create-wheel').classList.add('hidden');openCreate(b.dataset.create)});$('#play-truth').onclick=()=>{nav('chats');if(app.roomId)openGamePicker();else openHostLobby()};$$('.game-item').forEach(b=>b.onclick=()=>{nav('chats');openGamePicker()});$('.edit-profile').onclick=()=>app.profile?editProfile(app.profile.profile):showProfile(app.user?.handle);$('.profile-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-profile-tab]');if(b)loadProfileTab(b.dataset.profileTab)});$('.profile-banner').onclick=e=>{if(!e.target.closest('.profile-settings')&&app.user&&app.profile?.profile?.id===app.user.id)editCover();else if(!e.target.closest('.profile-settings')&&app.profile?.profile?.coverData)showFullImage(app.profile.profile.coverData)};$('#home-page').addEventListener('click',e=>{const b=e.target.closest('.feed-tab');if(b)return});
 if(localStorage.getItem('trude-data-saver')==='1')document.documentElement.classList.add('data-saver');try{const r=await api('/api/auth/me');app.user=r.user}catch{}updateProfile();await loadFeed();if(!app.user)openAuth('signup');
 if(location.hash.startsWith('#post/')){const id=location.hash.slice(6);setTimeout(()=>document.querySelector(`[data-post-id="${id}"]`)?.scrollIntoView(),200)}
}
async function joinRandom(){if(!requireLogin())return;try{const r=await api('/api/rooms');let room=r.rooms.find(x=>x.members<x.capacity);if(!room){const made=await send('/api/rooms',{title:'Random conversation · 30 min',capacity:20,duration:30});room={id:made.room}}await joinRoom(room.id)}catch(e){toast(e.message)}}
async function loadProfileTab(name){if(!app.profile)return;try{const r=await api(`/api/feed?tab=${encodeURIComponent(name)}`);app.profile.posts=r.posts;$$('[data-profile-tab]').forEach(b=>b.classList.toggle('chosen',b.dataset.profileTab===name));$('.profile-posts').innerHTML=r.posts.map(p=>`<button class="profile-tile" data-open-profile-post="${p.id}">${p.mediaUrl?`<img src="${p.mediaUrl}">`:`<span>✳</span><small>${esc(p.caption||p.body)}</small>`}</button>`).join('')||'<div class="empty-note">Nothing here yet.</div>'}catch(e){toast(e.message)}}
async function toggleFollow(id,button){if(!requireLogin())return;try{const r=await send(`/api/profiles/${id}/follow`);button.classList.toggle('following',r.following);button.textContent=r.following?'Following':'Follow';if(app.profile&&app.profile.profile.id===id){app.profile.following=r.following;app.profile.counts.followers+=r.following?1:-1;renderProfile()}}catch(e){toast(e.message)}}
async function findGlobalPost(){const match=location.hash.match(/^#post\/(\d+)/);if(!match)return;const id=match[1];nav('home');await loadFeed();document.querySelector(`[data-post-id="${id}"]`)?.scrollIntoView({behavior:'smooth'});}
window.openHostLobby=openHostLobby;
function openAuth(mode='login'){
 const signup=mode==='signup',forgot=mode==='forgot';let stage=mode;
 const title=signup?'Create your account':forgot?'Reset your password':'Welcome back';
 const fields=signup?'<label>Your name<input name="name" required minlength="2" maxlength="40" placeholder="How friends know you"></label><label>Choose a handle<input name="handle" required minlength="3" maxlength="24" pattern="[A-Za-z0-9_.]+" placeholder="yourname"></label><label>Email or mobile number<input name="identifier" required autocomplete="username" placeholder="you@gmail.com or +1…"></label><label>Password<input name="password" required minlength="10" type="password" autocomplete="new-password" placeholder="At least 10 characters"></label><p class="auth-footnote">Test mode: email/SMS verification is off. Use test contact details only.</p>':forgot?'<p>Enter your account email or number. A local test code appears here because email/SMS delivery is not connected.</p><label>Email or mobile number<input name="identifier" required placeholder="Account email or number"></label>':'<label>Email or mobile number<input name="identifier" required autocomplete="username" placeholder="you@gmail.com or +1…"></label><label>Password<input name="password" required type="password" autocomplete="current-password" placeholder="Your password"></label><button type="button" class="text-btn forgot-trigger">Forgot password?</button>';
 const intro=signup?'A good place to make a little noise.':forgot?'We will help you get back into your account.':'Sign in and pick up where you left off.';
 const switchText=signup?'Already have an account?':forgot?'Remembered it?':'New to Trude?',switchAction=signup||forgot?'login':'signup',switchLabel=signup||forgot?'Sign in':'Create an account';
 modal(title,'<div class="auth-mark">t</div><p class="auth-lede">'+intro+'</p><form id="auth-form" class="auth-form">'+fields+'<div id="auth-error" class="form-error"></div><button class="modal-primary auth-submit" type="submit">'+(signup?'Create account':forgot?'Request reset':'Sign in')+'</button></form><button class="google-signin" type="button" data-auth="google"><span>G</span> Continue with Google</button><div class="auth-divider"><span>or</span></div><p class="auth-switch">'+switchText+' <button type="button" class="text-btn" data-auth="'+switchAction+'">'+switchLabel+'</button></p>');
 $('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget).entries()),error=$('#auth-error');error.textContent='';try{
  if(stage==='forgot'){const r=await send('/api/auth/forgot',body);if(!r.resetCode){error.textContent=r.message;return}$('#auth-form').innerHTML='<input type="hidden" name="identifier" value="'+esc(body.identifier)+'"><div class="reset-code-display">Local test code <b>'+esc(r.resetCode)+'</b></div><label>Reset code<input name="code" inputmode="numeric" autocomplete="one-time-code" required maxlength="6"></label><label>New password<input name="password" type="password" required minlength="10" autocomplete="new-password"></label><div id="auth-error" class="form-error"></div><button class="modal-primary auth-submit">Save new password</button>';stage='reset';return}
  if(stage==='reset'){await send('/api/auth/reset',body);openAuth('login');toast('Password updated. Sign in again.');return}
  const result=await send('/api/auth/'+(signup?'signup':'login'),body);app.user=result.user;closeModal();updateProfile();await loadFeed();toast(signup?'Welcome to Trude ✳':'You are signed in');if(app.page==='lobby')loadLobbyDirectory();if(app.page==='chats')loadRooms()
 }catch(err){error.textContent=err.message}});
 $$('[data-auth]').forEach(b=>b.onclick=()=>b.dataset.auth==='google'?toast('Google sign-in needs a configured Trude OAuth client. Use an email or mobile test account.'):openAuth(b.dataset.auth));$('.forgot-trigger')?.addEventListener('click',()=>openAuth('forgot'));
}
window.openAuth=openAuth;
bootstrap().catch(e=>toast(e.message));
